import{_ as o,o as r,c as a,a2 as t}from"./chunks/framework.0AV_2kjq.js";const p=JSON.parse('{"title":"Terms of Service","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://moviplayer.com/docs/terms-of-service"}]]},"headers":[],"relativePath":"terms-of-service.md","filePath":"terms-of-service.md"}'),i={name:"terms-of-service.md"};function n(s,e,l,c,h,d){return r(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="terms-of-service" tabindex="-1">Terms of Service <a class="header-anchor" href="#terms-of-service" aria-label="Permalink to &quot;Terms of Service&quot;">​</a></h1><p><strong>Last updated:</strong> August 18, 2026</p><p><strong>Movi Player — Web Player, Chrome Extension &amp; Google Drive integration</strong></p><p>These Terms of Service (&quot;Terms&quot;) govern your use of Movi Player, an open-source video player that runs in your web browser. By using Movi Player — including the website at <a href="https://moviplayer.com" target="_blank" rel="noreferrer">moviplayer.com</a>, the Chrome extension, or the &quot;Open with Movi Player&quot; Google Drive integration — you agree to these Terms. If you do not agree, please do not use the service.</p><h2 id="description-of-service" tabindex="-1">Description of Service <a class="header-anchor" href="#description-of-service" aria-label="Permalink to &quot;Description of Service&quot;">​</a></h2><p>Movi Player is a client-side video player powered by WebCodecs and FFmpeg WebAssembly. All video decoding and playback happen locally in your browser.</p><p><strong>We do not host, store, index, or provide any video content.</strong> Movi Player ships with no library, no catalogue, and no search over third-party media. Every video played is one you supply — a file on your device, a file in your own Google Drive, or a URL you paste.</p><p><strong>How your video reaches the player:</strong></p><ul><li><strong>Local files</strong> (drag-and-drop or file picker) are read entirely on your device. They are never uploaded, and never touch any server we operate.</li><li><strong>Google Drive files</strong> stream directly from Google&#39;s servers to your browser.</li><li><strong>URLs you paste</strong> are normally fetched by your browser directly from the host you named. Where that host does not permit cross-origin playback, the request may pass through a fetch relay we operate purely to satisfy browser CORS rules. That relay is a transient conduit: it does not store, cache, transcode, index, or retain the media, and it only forwards bytes that you specifically requested. Embedded players (<code>/embed</code>) never use the relay at all.</li></ul><h2 id="acceptable-use" tabindex="-1">Acceptable Use <a class="header-anchor" href="#acceptable-use" aria-label="Permalink to &quot;Acceptable Use&quot;">​</a></h2><p>You are responsible for the content you choose to play with Movi Player. You agree to use the service only with content that you own, or are otherwise legally permitted to access and play, and only in compliance with all applicable laws.</p><p>You may not use Movi Player to access, reproduce, distribute, publicly perform, or circumvent access controls on content in violation of any third party&#39;s rights, and you may not use it for any content that is unlawful in your jurisdiction.</p><p>We do not monitor, and have no practical ability to monitor, what any visitor plays — decoding happens on the visitor&#39;s own device. Responsibility for the legality of a chosen source rests with the person who chose it.</p><h2 id="reporting-infringing-or-unlawful-content" tabindex="-1">Reporting Infringing or Unlawful Content <a class="header-anchor" href="#reporting-infringing-or-unlawful-content" aria-label="Permalink to &quot;Reporting Infringing or Unlawful Content&quot;">​</a></h2><p>We take rights-holder and abuse reports seriously and act on valid notices.</p><p>Because we host no content, the usual remedy is to have the material removed at its actual source. Where a URL is reaching a visitor&#39;s browser through our fetch relay, we can and will block that URL or host on request from a rights holder or their authorised agent.</p><p>To submit a notice, email <strong><a href="mailto:abuse@moviplayer.com" target="_blank" rel="noreferrer">abuse@moviplayer.com</a></strong> with:</p><ol><li>Identification of the copyrighted work or other right you claim is infringed.</li><li>The specific URL(s) at issue.</li><li>Your contact details (name, address, telephone, email).</li><li>A statement that you have a good-faith belief the use is not authorised by the rights holder, its agent, or the law.</li><li>A statement, under penalty of perjury, that the information in the notice is accurate and that you are the rights holder or authorised to act on their behalf.</li><li>Your physical or electronic signature.</li></ol><p>We aim to acknowledge notices within 48 hours. If you believe a URL was blocked in error, you may send a counter-notice to the same address.</p><p><strong>Repeat infringers.</strong> Hosts and URLs that are the subject of repeated valid notices are blocked permanently at the relay.</p><h2 id="grievance-officer-india" tabindex="-1">Grievance Officer (India) <a class="header-anchor" href="#grievance-officer-india" aria-label="Permalink to &quot;Grievance Officer (India)&quot;">​</a></h2><p>In accordance with the Information Technology Act, 2000 and the Information Technology (Intermediary Guidelines and Digital Media Ethics Code) Rules, 2021:</p><ul><li><strong>Grievance Officer:</strong> Ujjwal Kashyap</li><li><strong>Email:</strong> <a href="mailto:grievance@moviplayer.com" target="_blank" rel="noreferrer">grievance@moviplayer.com</a></li></ul><p>Complaints are acknowledged within 24 hours and resolved within 15 days of receipt. Content will be removed or access disabled within 36 hours of receiving an order from a court of competent jurisdiction or an appropriate government agency.</p><h2 id="visitor-comments" tabindex="-1">Visitor Comments <a class="header-anchor" href="#visitor-comments" aria-label="Permalink to &quot;Visitor Comments&quot;">​</a></h2><p>The feedback section on moviplayer.com accepts public comments. You are responsible for what you post. Do not post unlawful, defamatory, abusive, or infringing material, spam, or another person&#39;s private information. We may remove any comment at our discretion, and we remove unlawful comments on notice via the contact addresses above.</p><h2 id="google-drive-integration" tabindex="-1">Google Drive Integration <a class="header-anchor" href="#google-drive-integration" aria-label="Permalink to &quot;Google Drive Integration&quot;">​</a></h2><p>Movi Player offers an optional integration that lets you play video files stored in your own Google Drive.</p><ul><li>Access is <strong>read-only</strong>. Movi Player never edits, deletes, moves, shares, renames, or uploads any file in your Drive.</li><li>When you open a video, Movi Player streams the file&#39;s bytes directly from Google&#39;s servers to your browser (using ranged HTTP requests) and decodes them locally for playback.</li><li>File contents are <strong>never sent to, stored on, or logged by any server operated by us</strong>, and are never shared with any third party.</li><li>You may revoke Movi Player&#39;s access to your Google account at any time via <a href="https://myaccount.google.com/permissions" target="_blank" rel="noreferrer">Google Account permissions</a>.</li></ul><p>Movi Player&#39;s use of information received from Google APIs adheres to the <a href="https://developers.google.com/terms/api-services-user-data-policy" target="_blank" rel="noreferrer">Google API Services User Data Policy</a>, including the Limited Use requirements.</p><h2 id="open-source-license" tabindex="-1">Open Source &amp; License <a class="header-anchor" href="#open-source-license" aria-label="Permalink to &quot;Open Source &amp; License&quot;">​</a></h2><p>Movi Player is open-source software released under the Apache-2.0 License. You may review, use, and modify the source code at <a href="https://github.com/MrUjjwalG/movi-player" target="_blank" rel="noreferrer">github.com/MrUjjwalG/movi-player</a> in accordance with that license.</p><h2 id="disclaimer-of-warranties" tabindex="-1">Disclaimer of Warranties <a class="header-anchor" href="#disclaimer-of-warranties" aria-label="Permalink to &quot;Disclaimer of Warranties&quot;">​</a></h2><p>Movi Player is provided <strong>&quot;as is&quot; and &quot;as available&quot;</strong>, without warranties of any kind, whether express or implied, including but not limited to warranties of merchantability, fitness for a particular purpose, and non-infringement. We do not warrant that the service will be uninterrupted, error-free, or compatible with every file, codec, browser, or device.</p><h2 id="limitation-of-liability" tabindex="-1">Limitation of Liability <a class="header-anchor" href="#limitation-of-liability" aria-label="Permalink to &quot;Limitation of Liability&quot;">​</a></h2><p>To the maximum extent permitted by law, in no event shall the developers or contributors of Movi Player be liable for any indirect, incidental, special, consequential, or punitive damages, or any loss of data, arising out of or related to your use of — or inability to use — the service.</p><h2 id="third-party-services" tabindex="-1">Third-Party Services <a class="header-anchor" href="#third-party-services" aria-label="Permalink to &quot;Third-Party Services&quot;">​</a></h2><p>The Google Drive integration relies on Google APIs and is subject to <a href="https://policies.google.com/terms" target="_blank" rel="noreferrer">Google&#39;s Terms of Service</a> and the <a href="https://developers.google.com/terms/api-services-user-data-policy" target="_blank" rel="noreferrer">Google API Services User Data Policy</a>. The site is served through Cloudflare, and the comments form is protected by Cloudflare Turnstile. Your use of any content you play remains subject to the terms of the source from which it originates.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>Your use of Movi Player is also governed by our <a href="/movi-player/privacy-policy">Privacy Policy</a>, which explains what data is (and is not) collected.</p><h2 id="changes-to-these-terms" tabindex="-1">Changes to These Terms <a class="header-anchor" href="#changes-to-these-terms" aria-label="Permalink to &quot;Changes to These Terms&quot;">​</a></h2><p>We may update these Terms from time to time. When we do, we will revise the &quot;Last updated&quot; date above. Continued use of Movi Player after changes take effect constitutes acceptance of the revised Terms.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Abuse and copyright notices:</strong> <a href="mailto:abuse@moviplayer.com" target="_blank" rel="noreferrer">abuse@moviplayer.com</a></li><li><strong>Grievances (India):</strong> <a href="mailto:grievance@moviplayer.com" target="_blank" rel="noreferrer">grievance@moviplayer.com</a></li><li><strong>Everything else:</strong> open an issue on our <a href="https://github.com/MrUjjwalG/movi-player/issues" target="_blank" rel="noreferrer">GitHub repository</a></li></ul>',44)])])}const m=o(i,[["render",n]]);export{p as __pageData,m as default};
